        self._tokens = itertools.count(1)

    def add(self, job_id):
        with self._lock:
            if job_id in self._jobs:
                # already present: ensure it is claimable (queued/running), leave as-is
                return
            self._jobs[job_id] = {
                'state': 'queued',
                'expiry': None,
                'token': None,
                'worker': None,
            }
            self._order.append(job_id)

    def _next_token(self):
        return next(self._tokens)

    def claim(self, worker, now, ttl):
        if ttl is None or ttl <= 0:
            return None
        with self._lock:
            # find first eligible id in insertion order
            for job_id in self._order:
